import{Z as e,e as o,f as n,a0 as a}from"./chunks/framework.DmpHOl9T.js";const m=JSON.parse('{"title":"IFTTT","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/automations/ifttt.md","filePath":"integrations/automations/ifttt.md","lastUpdated":1780377007000}'),i={name:"integrations/automations/ifttt.md"};function s(r,t,l,h,c,g){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="ifttt" tabindex="-1">IFTTT <a class="header-anchor" href="#ifttt" aria-label="Permalink to &quot;IFTTT&quot;">​</a></h1><p>Connect IFTTT to pass submitted answers to an automated workflow. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Automations</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>IFTTT</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-ifttt-api" tabindex="-1">Step 2. Connect to the IFTTT API <a class="header-anchor" href="#step-2-connect-to-the-ifttt-api" aria-label="Permalink to &quot;Step 2. Connect to the IFTTT API&quot;">​</a></h3><ol><li>Go to the <a href="https://ifttt.com/create" target="_blank">IFTTT Create page</a>.</li><li>Click <strong>If This → Add</strong>, then search for and select <strong>Webhooks</strong>.</li><li>Choose <strong>Receive a web request</strong> and enter an <strong>Event Name</strong> (e.g. <code>form_submission</code>). Make a note of <strong>Event Name</strong> for later.</li><li>Click <strong>Then That → Add</strong>, and choose an action like sending an email, Slack message, Google Sheets, etc.</li><li>Complete the applet and click <strong>Finish</strong>.</li></ol><h3 id="step-3-get-your-webhook-key" tabindex="-1">Step 3. Get Your Webhook Key <a class="header-anchor" href="#step-3-get-your-webhook-key" aria-label="Permalink to &quot;Step 3. Get Your Webhook Key&quot;">​</a></h3><ol><li>Visit <a href="https://ifttt.com/maker_webhooks" target="_blank"><a href="https://ifttt.com/maker_webhooks" target="_blank" rel="noreferrer">https://ifttt.com/maker_webhooks</a></a>.</li><li>Click <strong>Documentation</strong>.</li><li>Copy your <strong>Webhook Key</strong> from the URL shown (<code>https://maker.ifttt.com/use/XXXXX</code>).</li><li>Paste it into the <strong>Webhook Key</strong> field in Formie.</li><li>Enter the same <strong>Event Name</strong> you used in IFTTT.</li></ol><h3 id="step-4-form-settings" tabindex="-1">Step 4. Form Settings <a class="header-anchor" href="#step-4-form-settings" aria-label="Permalink to &quot;Step 4. Form Settings&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Choose the destination workflow or URL supported by this integration and map the submitted values it needs. Use a test destination while checking the connection.</li><li>Click <strong>Save</strong> to save the form.</li><li>Click on the <strong>Send Test Payload</strong> button to send dummy content to the URL.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Inspect the receiving workflow’s run history or request log. Check both the received values and the outcome of any following steps.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',13)])])}const f=e(i,[["render",s]]);export{m as __pageData,f as default};
